 import { useEffect, useState } from "react";
 import { useSearchParams } from "react-router";
 import RestCard from "./RestCard";
 import Shimmer from "./Shimmer";

 export default function Restaurant(){
     const [searchParams] = useSearchParams();
     const category = searchParams.get("category") || "";
     const [restData, setRestData] = useState([]);
     const [isLoading, setIsLoading] = useState(true);
     const [error, setError] = useState("");
     const [retryCount, setRetryCount] = useState(0);

     useEffect(() => {
         let isCurrentRequest = true;

         async function fetchData() {
             setIsLoading(true);
             setError("");

             try {
                 const proxyServer = "https://cors-anywhere.herokuapp.com/";
                 const swiggyAPI = "https://www.swiggy.com/dapi/restaurants/list/v5?lat=28.7040592&lng=77.10249019999999&is-seo-homepage-enabled=true";
                 const response = await fetch(proxyServer + swiggyAPI);

                 if (!response.ok) {
                     if (response.status === 403) {
                         throw new Error("The shared API proxy denied the request. Open the proxy access page below, request temporary access, then retry.");
                     }
                     throw new Error(`Restaurant data request failed (HTTP ${response.status}).`);
                 }

                 const contentType = response.headers.get("content-type") || "";
                 if (!contentType.includes("application/json")) {
                     throw new Error("Swiggy returned a webpage instead of restaurant data. Its API may be temporarily unavailable.");
                 }

                 const data = await response.json();
                 const restaurants = data?.data?.cards?.[1]?.card?.card?.gridElements?.infoWithStyle?.restaurants;
                 if (!Array.isArray(restaurants) || restaurants.length === 0) {
                     throw new Error("The restaurant data could not be found in the API response.");
                 }

                 if (isCurrentRequest) {
                     setRestData(restaurants);
                 }
             } catch (requestError) {
                 if (isCurrentRequest) {
                     setError(requestError instanceof Error ? requestError.message : "Unable to load restaurants.");
                 }
             } finally {
                 if (isCurrentRequest) {
                     setIsLoading(false);
                 }
             }
         }

         fetchData();
         return () => {
             isCurrentRequest = false;
         };
     }, [retryCount]);

     if (isLoading) {
         return <Shimmer></Shimmer>
     }

     if (error) {
         return (
             <div className="w-[80%] mx-auto mt-20 text-center">
                 <p className="text-xl font-semibold">{error}</p>
                 {error.includes("proxy denied") && (
                     <a
                         className="text-blue-600 underline block mt-3"
                         href="https://cors-anywhere.herokuapp.com/corsdemo"
                         target="_blank"
                         rel="noreferrer"
                     >
                         Open the proxy access page
                     </a>
                 )}
                 <button
                     className="mt-4 rounded bg-orange-500 px-4 py-2 text-white"
                     onClick={() => setRetryCount((count) => count + 1)}
                 >
                     Retry
                 </button>
             </div>
         );
     }

     return (
         <>
             {category && <h1 className="w-[80%] mx-auto mt-16 text-3xl font-bold">{category} restaurants</h1>}
             <div className="flex flex-wrap w-[80%] mx-auto mt-8 gap-5">
                 {(() => {
                     const normalizedCategory = category.toLowerCase().replace(/s$/, "");
                     const visibleRestaurants = category
                         ? restData.filter((restaurant) =>
                             (restaurant?.info?.cuisines || []).some((cuisine) =>
                                 cuisine.toLowerCase().includes(normalizedCategory)
                             )
                         )
                         : restData;

                     return visibleRestaurants.length > 0
                         ? visibleRestaurants.map((restInfo) => (
                             <RestCard key={restInfo?.info?.id} restInfo={restInfo}></RestCard>
                         ))
                         : <p className="w-full text-center text-xl">No restaurants found for {category}.</p>;
                 })()}
             </div>
         </>
     )

 }

