 export default function RestaurantMenu(){
     const {id} = useParams();
     const [selected, setSelected] = useState(null);
     const [restData, setRestData] = useState([]);
     const [isLoading, setIsLoading] = useState(true);
     const [error, setError] = useState("");
     const [retryCount, setRetryCount] = useState(0);

     useEffect(() => {
         let isCurrentRequest = true;

         async function fetchData() {
             setIsLoading(true);
             setError("");

             try {
                 const proxyServer = "https://cors-anywhere.herokuapp.com/";
                 const swiggyAPI = `https://www.swiggy.com/mapi/menu/pl?page-type=REGULAR_MENU&complete-menu=true&lat=28.7040592&lng=77.10249019999999&restaurantId=${id}`;
                 const response = await fetch(proxyServer + swiggyAPI);

                 if (!response.ok) {
                     if (response.status === 403) {
                         throw new Error("The shared API proxy denied the request. Open the proxy access page below, request temporary access, then retry.");
                     }
                     throw new Error(`Restaurant menu request failed (HTTP ${response.status}).`);
                 }

                 const data = await response.json();
                 if (data?.statusCode && data.statusCode !== 0) {
                     throw new Error(data?.statusMessage || "Swiggy could not load this restaurant menu.");
                 }

                 const cards = data?.data?.cards;
                 const regularCards = Array.isArray(cards)
                     ? cards.find((item) => {
                         const groupedCards = item?.card?.groupedCard?.cardGroupMap?.REGULAR?.cards;
                         return Array.isArray(groupedCards);
                     })?.card?.groupedCard?.cardGroupMap?.REGULAR?.cards
                     : undefined;

                 if (!Array.isArray(regularCards)) {
                     throw new Error("Swiggy did not return menu data for this restaurant. The restaurant may be unavailable, or Swiggy may have changed its API response.");
                 }

                 const menuSections = regularCards.filter((item) => {
                     const section = item?.card?.card;
                     return section && typeof section.title === "string";
                 });

                 if (menuSections.length === 0) {
                     throw new Error("This restaurant has no menu sections available.");
                 }

                 if (isCurrentRequest) {
                     setRestData(menuSections);
                 }
             } catch (requestError) {
                 if (isCurrentRequest) {
                     setError(requestError instanceof Error ? requestError.message : "Unable to load the restaurant menu.");
                 }
             } finally {
                 if (isCurrentRequest) {
                     setIsLoading(false);
                 }
             }
         }

         fetchData();
         return () => {
             isCurrentRequest = false;
         };
     }, [id, retryCount]);

     return(
         <div>

         <div className="w-[80%] mx-auto mt-20 mb-20">
           <Link to={`/city/delhi/${id}/search`}>
           <p className="w-full text-center py-4 rounded-4xl bg-gray-200 text-2xl">Search for Dishes</p>
