         <button className={`text-2xl py-2 px-4 border rounded-2xl ${selected==="nonveg"? "bg-red-500": "bg-gray-300"}`} onClick={()=>setSelected(selected==='nonveg'?null:'nonveg')}>Non veg</button>
         </div>

         <div className="w-[80%] mx-auto mt-20">
           {
             isLoading ? (
                 <p className="text-center text-xl">Loading menu...</p>
             ) : error ? (
                 <div className="text-center">
                     <p className="text-xl font-semibold">{error}</p>
                     {error.includes("proxy denied") && (
                         <a
                             className="text-blue-600 underline block mt-3"
                             href="https://cors-anywhere.herokuapp.com/corsdemo"
                             target="_blank"
                             rel="noreferrer"
                         >
                             Open the proxy access page
                         </a>
                     )}
                     <button
                         className="mt-4 rounded bg-orange-500 px-4 py-2 text-white"
                         onClick={() => setRetryCount((count) => count + 1)}
                     >
                         Retry
                     </button>
                 </div>
             ) : (
                 restData.map((menuItems) => (
                     <MenuCard key={menuItems?.card?.card?.title} menuItems={menuItems?.card?.card} foodselected={selected}></MenuCard>
                 ))
             )
           }
         </div>
         </div>
     )

 }

