                 <p className="mt-1 text-gray-600">{restaurant.info.cuisines.join(", ")}</p>
                 <Link to={`/city/delhi/${id}/search`}>
                     <p className="mt-8 w-full rounded-4xl bg-gray-200 py-4 text-center text-2xl">
