                     onClick={() => setSelected(selected === "veg" ? null : "veg")}
                 >
                     Veg
                 </button>
                 <button
                     className={`rounded-2xl border px-4 py-2 text-2xl ${selected === "nonveg" ? "bg-red-500" : "bg-gray-300"}`}
