                 </button>
             </div>

             <div className="mx-auto mt-8 w-[80%]">
                 {restaurant.menuSections.map((section) => (
                     <MenuCard key={section.title} menuItems={section} foodselected={selected}></MenuCard>
                 ))}
             </div>
         </main>
     );
 }

