 import { useSearchParams } from "react-router";
 import RestCard from "./RestCard";
 import { localRestaurants } from "../Utils/LocalRestaurantData";

 export default function Restaurant() {
     const [searchParams] = useSearchParams();
     const category = searchParams.get("category") || "";
     const normalizedCategory = category.toLowerCase().replace(/s$/, "");

     const visibleRestaurants = category
         ? localRestaurants.filter((restaurant) => {
             const cuisines = restaurant.info.cuisines || [];
             const dishes = restaurant.menuSections.flatMap((section) =>
                 section.itemCards.map((item) => item.card.info.name)
             );
             return [...cuisines, ...dishes].some((value) =>
                 value.toLowerCase().includes(normalizedCategory)
             );
         })
         : localRestaurants;

     return (
         <>
             <h1 className="w-[80%] mx-auto mt-16 text-3xl font-bold">
                 {category ? `${category} restaurants` : "Restaurants"}
             </h1>
             <div className="flex flex-wrap w-[80%] mx-auto mt-8 gap-5">
                 {visibleRestaurants.length > 0 ? (
                     visibleRestaurants.map((restInfo) => (
                         <RestCard key={restInfo.info.id} restInfo={restInfo}></RestCard>
                     ))
                 ) : (
                     <p className="w-full text-center text-xl">
                         No sample restaurants found for {category}.
                     </p>
                 )}
             </div>
         </>
     );
 }

