 import { useDispatch, useSelector } from "react-redux";
 import { Link } from "react-router";
 import { clearCart, decrementItem, incrementItem, removeItem } from "../Stored/CartSlicer";

 const formatPrice = (priceInPaise) =>
     new Intl.NumberFormat("en-IN", {
         style: "currency",
         currency: "INR",
         maximumFractionDigits: 0
     }).format(priceInPaise / 100);

 const getItemPrice = (item) => item.defaultPrice ?? item.price ?? 0;

 export default function Checkout() {
     const dispatch = useDispatch();
     const items = useSelector((state) => state.cartslice.items);
     const itemCount = items.reduce((total, item) => total + item.quantity, 0);
     const subtotal = items.reduce((total, item) => total + getItemPrice(item) * item.quantity, 0);

     return (
         <main className="min-h-screen bg-stone-50 px-4 py-10 text-stone-800 sm:px-6">
             <div className="mx-auto max-w-4xl">
                 <div className="mb-8 flex flex-wrap items-end justify-between gap-4">
                     <div>
                         <p className="text-sm font-semibold uppercase tracking-[0.18em] text-orange-600">Your order</p>
                         <h1 className="mt-1 text-3xl font-bold tracking-tight sm:text-4xl">Shopping cart</h1>
                         {itemCount > 0 && <p className="mt-2 text-sm text-stone-500">{itemCount} {itemCount === 1 ? "item" : "items"}</p>}
                     </div>
                     {items.length > 0 && (
                         <button
                             className="rounded-lg px-3 py-2 text-sm font-semibold text-stone-500 transition hover:bg-red-50 hover:text-red-700"
                             onClick={() => dispatch(clearCart())}
                         >
                             Clear cart
                         </button>
                     )}
                 </div>

                 {items.length === 0 ? (
                     <section className="rounded-2xl border border-stone-200 bg-white px-6 py-16 text-center shadow-sm">
                         <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-orange-50 text-3xl" aria-hidden="true">
                             🛒
                         </div>
                         <h2 className="mt-5 text-xl font-bold">Your cart is empty</h2>
                         <p className="mt-2 text-stone-500">Add something delicious from a restaurant menu to get started.</p>
                         <Link
                             className="mt-6 inline-flex rounded-xl bg-orange-600 px-5 py-3 font-semibold text-white transition hover:bg-orange-700"
                             to="/restaurant"
                         >
                             Browse restaurants
                         </Link>
                     </section>
                 ) : (
                     <div className="grid gap-6 md:grid-cols-[1fr_300px]">
                         <section className="divide-y divide-stone-100 rounded-2xl border border-stone-200 bg-white px-5 shadow-sm sm:px-6">
                             {items.map((item) => {
                                 const unitPrice = getItemPrice(item);
                                 return (
                                     <article key={item.id} className="flex items-center gap-4 py-5">
                                         <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-orange-50 text-lg font-bold text-orange-700">
                                             {item.name?.charAt(0)}
                                         </div>
                                         <div className="min-w-0 flex-1">
                                             <h2 className="truncate font-semibold">{item.name}</h2>
                                             <p className="mt-1 text-sm text-stone-500">{formatPrice(unitPrice)} each</p>
                                         </div>
                                         <div className="flex items-center rounded-lg border border-stone-200">
                                             <button
                                                 className="px-3 py-2 font-semibold text-stone-600 transition hover:bg-stone-100"
                                                 onClick={() => dispatch(decrementItem(item.id))}
                                                 aria-label={`Remove one ${item.name}`}
                                             >
                                                 −
